  webhookTitle: 'Disparador externo', webhookIdle: 'Un servicio externo puede iniciar este bot con una dirección y una clave privadas.',
  webhookActive: 'Envía una petición a esta dirección con la clave para iniciar una ejecución. Trata la clave como una contraseña.',
  webhookAddress: 'Dirección', webhookKey: 'Clave', webhookCreate: 'Crear webhook', webhookRemove: 'Quitar webhook',
